-- Same schema for SQLite (used by the automated tests)
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE quotations (id INTEGER PRIMARY KEY AUTOINCREMENT, tour_code TEXT NOT NULL, tour_name TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL, min_pax INTEGER NOT NULL, foc INTEGER NOT NULL DEFAULT 0, rate_usd REAL NOT NULL, rate_rmb REAL NOT NULL, pic TEXT NOT NULL DEFAULT '', final_selling REAL, selling_per_pax REAL NOT NULL, net_margin_per_pax REAL NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE quotation_items (id INTEGER PRIMARY KEY AUTOINCREMENT, quotation_id INTEGER NOT NULL REFERENCES quotations(id) ON DELETE CASCADE, position INTEGER NOT NULL, type TEXT NOT NULL CHECK (type IN ('main','variable','optional')), description TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'IDR' CHECK (currency IN ('IDR','USD','RMB')), nett_vendor REAL NOT NULL, divide_by INTEGER, profit_percent REAL NOT NULL DEFAULT 0, qty_days REAL NOT NULL DEFAULT 1, remark TEXT NOT NULL DEFAULT '');
